// src/lib/attribute-charging.ts
function chargesForAttributes(values) {
  return !values?.isDroid;
}
function primaryAttributeBaseline(input) {
  if (input.isDroid) return input.hardwareBase;
  const field = Number(input.baselineField);
  return input.baselineField == null || Number.isNaN(field) ? input.hardwareBase : field;
}

