var getPrimaryAttributes = (formValues, globalModifiers) => {
  let hardwareBaseST = BASE_ATTRIBUTE_VALUE;
  let hardwareBaseDX = BASE_ATTRIBUTE_VALUE;
  let hardwareBaseIQ = BASE_ATTRIBUTE_VALUE;
  let hardwareBaseHT = BASE_ATTRIBUTE_VALUE;
  let liftingStBonus = 0;
  let strikingStBonus = 0;
  if (formValues.isDroid && formValues.droidBuild) {
    const build = formValues.droidBuild;
    const chassis = DROID_CHASSIS.find((c) => c.id === build.chassisId);
    hardwareBaseST = chassis?.st ?? 10;
    hardwareBaseIQ = governingDroidIq(build) ?? 10;
    hardwareBaseDX = 10;
    hardwareBaseHT = 10;
    const distinct = (ids) => [...new Set(ids.filter((id) => Boolean(id)))];
    const armIds = distinct((build.arms ?? []).map((a) => a.componentId));
    const legIds = distinct((build.legs ?? []).map((l) => l.componentId));
    const mountIds = distinct([
      ...(build.legs ?? []).map((l) => l.motiveMountId),
      ...build.chassisMods?.motiveMountIds ?? []
    ]);
    const upgradeIds = distinct([
      build.chassisMods?.actuatorId,
      build.chassisMods?.wiringId,
      build.head?.externalModId,
      ...(build.arms ?? []).map((a) => a.actuatorId),
      ...(build.arms ?? []).map((a) => a.wiringId),
      ...(build.legs ?? []).map((l) => l.actuatorId),
      ...(build.legs ?? []).map((l) => l.wiringId),
      ...build.chassisMods?.auxiliaryIds ?? [],
      ...build.chassisMods?.utilityIds ?? []
    ]);
    for (const id of armIds) {
      const arm = DROID_ARMS.find((a) => a.id === id);
      liftingStBonus += arm?.liftingSt ?? 0;
      strikingStBonus += arm?.strikingSt ?? 0;
    }
    for (const id of legIds) {
      const strut = DROID_MOTIVE_STRUTS.find((s) => s.id === id);
      liftingStBonus += strut?.liftingSt ?? 0;
      strikingStBonus += strut?.strikingSt ?? 0;
    }
    for (const id of mountIds) {
      const mount = DROID_MOTIVE_MOUNTS.find((m) => m.id === id);
      liftingStBonus += mount?.liftingSt ?? 0;
    }
    for (const id of upgradeIds) {
      const up = DROID_UPGRADES.find((u) => u.id === id);
      liftingStBonus += up?.stBonus ?? 0;
      strikingStBonus += up?.strikingStBonus ?? 0;
      hardwareBaseDX += up?.dxBonus ?? 0;
    }
  }
  const restingValue = (hardwareBase, baselineField) => primaryAttributeBaseline({ hardwareBase, baselineField, isDroid: formValues.isDroid });
  const rawStrength = formValues.strength ?? restingValue(hardwareBaseST, formValues.stBaseline);
  const rawDexterity = formValues.dexterity ?? restingValue(hardwareBaseDX, formValues.dxBaseline);
  const rawIQ = formValues.iq ?? restingValue(hardwareBaseIQ, formValues.iqBaseline);
  const rawHealth = formValues.health ?? restingValue(hardwareBaseHT, formValues.htBaseline);
  const effectiveStrength = rawStrength + (globalModifiers?.strength || 0);
  const effectiveDexterity = rawDexterity + (globalModifiers?.dexterity || 0);
  const effectiveIQ = rawIQ + (globalModifiers?.iq || 0);
  const effectiveHealth = rawHealth + (globalModifiers?.health || 0);
  return {
    rawStrength,
    rawDexterity,
    rawIQ,
    rawHealth,
    effectiveStrength,
    effectiveDexterity,
    effectiveIQ,
    effectiveHealth,
    hardwareBases: { strength: hardwareBaseST, dexterity: hardwareBaseDX, iq: hardwareBaseIQ, health: hardwareBaseHT },
    liftingStLevels: liftingStBonus,
    strikingStLevels: strikingStBonus,
    armStLevels: 0
  };
};

// src/lib/mental-attributes.ts
function baseMentalAttributes(values, iq) {
  if (values?.isDroid && values?.droidBuild) {
    const build = values.droidBuild;
    const processor = DROID_PROCESSORS.find((p) => p.id === build?.head?.processorId);
    const coProcessor = DROID_PROCESSORS.find((p) => p.id === build?.head?.coProcessorId);
    const droidBaseIQ = processor?.iq ?? 10;
    return {
      will: droidBaseIQ + (processor?.willBonus ?? 0) + (coProcessor?.willBonus ?? 0),
      perception: droidBaseIQ + (processor?.perBonus ?? 0) + (coProcessor?.perBonus ?? 0)
    };
  }
  return { will: iq, perception: iq };
}

