function conditionalBonusesFromFittedMods(item) {
  const slot = String(item?.slot ?? "").trim();
  if (!slot) return [];
  const out = [];
  for (const material of item?.materials ?? []) {
    const family = String(material?.name ?? "").trim();
    if (!family) continue;
    const mod = ARMOR_MOD_DATA.find((m) => m.name === `${family} (${slot})` && (m.conditionalBonuses?.length ?? 0) > 0);
    if (mod) out.push({ mod, bonuses: mod.conditionalBonuses ?? [] });
  }
  return out;
}
function typedResistanceFromFittedMods(item) {
  const slot = String(item?.slot ?? "").trim();
  if (!slot) return [];
  const out = [];
  for (const material of item?.materials ?? []) {
    const family = String(material?.name ?? "").trim();
    if (!family) continue;
    const mod = ARMOR_MOD_DATA.find((m) => m.name === `${family} (${slot})` && (Number(m.drBonus) || 0) > 0 && String(m.drVs ?? "").trim().length > 0);
    if (mod) out.push({ bonus: Number(mod.drBonus) || 0, vs: String(mod.drVs).trim() });
  }
  return out;
}

