        totalModCost += weapon.cost;
        notes.push(
          `${weapon.name}: Installs a ${weapon.name}. Damage: ${weapon.damage} ${weapon.damageType}.`.replace(/\s+\./g, ".") + (weapon.notes ? ` ${weapon.notes}` : "")
        );
