// src/lib/starship-mod-alias-migration.ts
var STARSHIP_MOD_ALIASES = new Map(
  STARSHIP_MODS.filter((m) => m.starshipName && m.starshipName !== m.name).map((m) => [m.starshipName, m.name])
);
function migrateStarshipModAliases(ship) {
  if (!ship) return false;
  let clearedADuplicate = false;
  for (const field of STARSHIP_SLOT_FIELDS) {
    const value = ship[field];
    if (typeof value !== "string") continue;
    const canonical = STARSHIP_MOD_ALIASES.get(value);
    if (!canonical) continue;
    const canonicalHeldElsewhere = STARSHIP_SLOT_FIELDS.some(
      (other) => other !== field && ship[other] === canonical
    );
    if (canonicalHeldElsewhere) {
      ship[field] = "None";
      clearedADuplicate = true;
    } else {
      ship[field] = canonical;
    }
  }
  return clearedADuplicate;
}

