function readyToPlay(data) {
  const charge = (rows) => (rows ?? []).map((row2) => Number(row2.points ?? 0) === 0 ? row2 : { ...row2, baselinePoints: 0 });
  return {
    ...data,
    // The character paid for its own attributes.
    stBaseline: 10,
    dxBaseline: 10,
    iqBaseline: 10,
    htBaseline: 10,
    advantages: charge(data.advantages),
    disadvantages: charge(data.disadvantages),
    skills: charge(data.skills),
    /*
              Ch6 prices every quirk at -1; the templates recorded them at 0.
    
              The baseline is not unconditional, though. Ch18 lists Rokarr's
              "Quirk (Roars when angered)" under Racial Package (Free, Inherent),
              exactly as it lists his Fur and his Bad Temper - so a quirk that
              arrives already cancelling itself out is one his species gave him and
              keeps its baseline. Zeroing every baseline here would have charged
              him for being a Wookiee.
            */
    quirks: (data.quirks ?? []).map((q) => {
      const points = Number(q.points) || QUIRK_POINT_COST;
      const arrivedFree = Number(q.points ?? 0) !== 0 && Number(q.baselinePoints ?? 0) === Number(q.points);
      return { ...q, points, baselinePoints: arrivedFree ? points : 0 };
    }),
    forcePowers: (data.forcePowers ?? []).map((f) => ({ ...f, baselinePoints: 0 })),
    /*
      Forms cost CP (Ch9, ruled 2026-08-28) - a finished character paid for
      the tiers it knows, so the baseline is zeroed and the point engine
      bills getFormDetails(...).cpCost, the same shape as Force powers.
    */
    lightsaberForms: (data.lightsaberForms ?? []).map((f) => ({ ...f, baselinePoints: 0 }))
  };
}

